class Strategy(bt.Strategy):
    params = (
        ('fast_period', 10),
        ('slow_period', 30),
    )

    def __init__(self):
        self.data_close = self.datas[0].close
        self.fast_sma = bt.indicators.SimpleMovingAverage(self.data_close, period=self.params.fast_period)
        self.slow_sma = bt.indicators.SimpleMovingAverage(self.data_close, period=self.params.slow_period)

    def next(self):
        if self.fast_sma > self.slow_sma:
            self.order_target_percent(target=1.0)
        elif self.fast_sma < self.slow_sma:
            self.close()

class Strategy(bt.Strategy):
    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=20)
        self.rsi = bt.indicators.RSI(self.data.close, period=14)

    def next(self):
        if not self.position:
            if self.rsi < 30 and self.data.close > self.sma:
                self.order_target_percent(target=1.0)
        else:
            if self.rsi > 70:
                self.close()

class Strategy(bt.Strategy):
    params = (
        ('short_window', 20),
        ('long_window', 50),
    )

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.sma_short = bt.indicators.SimpleMovingAverage(self.datas[0], period=self.params.short_window)
        self.sma_long = bt.indicators.SimpleMovingAverage(self.datas[0], period=self.params.long_window)
        self.order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.sma_short[0] > self.sma_long[0]:
                self.order = self.buy()
        else:
            if self.sma_short[0] < self.sma_long[0]:
                self.order = self.close()

